from pathlib import Path
from typing import Optional

from tau2.data_model.tasks import Task
from tau2.domains.retail.data_model import RetailDB
from tau2.domains.retail.tools import RetailTools
from tau2.domains.retail.utils import (
    RETAIL_DB_PATH,
    RETAIL_POLICY_PATH,
    RETAIL_TASK_SET_PATH,
)
from tau2.environment.environment import Environment
from tau2.environment.regional import DomainRegionalSettings
from tau2.utils import load_file


def get_environment(
    db: Optional[RetailDB] = None,
    solo_mode: bool = False,
    policy: str | None = None,
    regional_settings: DomainRegionalSettings | None = None,
) -> Environment:
    if solo_mode:
        raise ValueError("Retail domain does not support solo mode")
    if db is None:
        db = RetailDB.load(RETAIL_DB_PATH)
    else:
        db = db.model_copy(deep=True)
    tools = RetailTools(db, regional_settings=regional_settings)
    if policy is None:
        with open(RETAIL_POLICY_PATH, "r") as fp:
            policy = fp.read()
    return Environment(
        domain_name="retail",
        policy=policy,
        tools=tools,
    )


def get_tasks(task_split_name: Optional[str] = "base") -> list[Task]:
    tasks = load_file(RETAIL_TASK_SET_PATH)
    tasks = [Task.model_validate(task) for task in tasks]
    if task_split_name is None:
        return tasks
    task_splits = get_tasks_split()
    if task_split_name not in task_splits:
        raise ValueError(
            f"Invalid task split name: {task_split_name}. Valid splits are: {task_splits.keys()}"
        )
    tasks = [task for task in tasks if task.id in task_splits[task_split_name]]
    return tasks


def get_tasks_split() -> dict[str, list[str]]:
    split_file = (
        Path(RETAIL_TASK_SET_PATH).parent
        / f"split_{Path(RETAIL_TASK_SET_PATH).stem}.json"
    )
    return load_file(split_file)

